} from '@nestjs/common';
import {
  type ArtifactAccessResponse,
  type SetCompanyAccessOptions,
  type SetShareLinkOptions,
  type SharePeopleOptions,
  type UpdatePersonAccessOptions,
  setCompanyAccessRequestSchema,
  setShareLinkRequestSchema,
  sharePeopleRequestSchema,
  updatePersonAccessRequestSchema,
} from '@artifact-hub/shared';
import { CurrentActor } from '../auth/auth.decorators.js';
import type { Actor } from '../auth/auth.types.js';
import { ZodValidationPipe } from '../common/validation/zod-validation.pipe.js';
import { SharingService } from './sharing.service.js';

/** Access settings of an artifact; owner only. Every change returns the settings as they are now. */
@Controller('artifacts/:id/access')
export class SharingController {
  constructor(private readonly sharing: SharingService) {}

  @Get()
  async get(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.getAccess(actor, artifactId) };
  }

  @Put('company')
  async setCompany(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Body(new ZodValidationPipe(setCompanyAccessRequestSchema)) options: SetCompanyAccessOptions,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.setCompanyAccess(actor, artifactId, options) };
  }

  /** Answers 422 `SHARE_RECIPIENT_UNKNOWN`, listing them, if any email has no account. */
  @Post('people')
  async sharePeople(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Body(new ZodValidationPipe(sharePeopleRequestSchema)) options: SharePeopleOptions,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.sharePeople(actor, artifactId, options) };
  }

  @Patch('people/:userId')
  async updatePerson(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Param('userId') userId: string,
    @Body(new ZodValidationPipe(updatePersonAccessRequestSchema))
    changes: UpdatePersonAccessOptions,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.updatePerson(actor, artifactId, userId, changes) };
  }

  @Delete('people/:userId')
  async removePerson(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Param('userId') userId: string,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.removePerson(actor, artifactId, userId) };
  }

  /** Turns the link on, or changes its expiry or version; the URL stays the same. */
  @Put('link')
  async setLink(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
    @Body(new ZodValidationPipe(setShareLinkRequestSchema)) options: SetShareLinkOptions,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.setLink(actor, artifactId, options) };
  }

  @Delete('link')
  async turnOffLink(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.turnOffLink(actor, artifactId) };
  }

  /** A new URL for the link; the old one stops working. */
  @Post('link/reset')
  @HttpCode(HttpStatus.OK)
  async resetLink(
    @CurrentActor() actor: Actor,
    @Param('id') artifactId: string,
  ): Promise<ArtifactAccessResponse> {
    return { access: await this.sharing.resetLink(actor, artifactId) };
  }
}
import { DynamicModule, Module } from '@nestjs/common';
import { APP_FILTER } from '@nestjs/core';
import { LoggerModule } from 'nestjs-pino';
import { ApiTokenAuthenticatorService } from './api-tokens/api-token-authenticator.service.js';
import { ApiTokensModule } from './api-tokens/api-tokens.module.js';
import { ArtifactsModule } from './artifacts/artifacts.module.js';
import { AuthModule } from './auth/auth.module.js';
import { ClientConfigModule } from './client-config/client-config.module.js';
import { CommentsModule } from './comments/comments.module.js';
import { AllExceptionsFilter } from './common/errors/all-exceptions.filter.js';
import { buildLoggerParams } from './common/logging/logger.config.js';
import { RateLimitModule } from './common/rate-limit/rate-limit.module.js';
import { ConfigModule } from './config/config.module.js';
import type { Env } from './config/config.types.js';
import { DatabaseModule } from './database/database.module.js';
import { HealthModule } from './health/health.module.js';
import { McpModule } from './mcp/mcp.module.js';
import { SharingModule } from './sharing/sharing.module.js';
import { UploadSessionsModule } from './uploads/sessions/upload-sessions.module.js';
import { WebModule } from './web/web.module.js';

@Module({})
export class AppModule {
  static register(env: Env): DynamicModule {
    return {
      module: AppModule,
      imports: [
        ConfigModule.forRoot(env),
        LoggerModule.forRoot(buildLoggerParams(env)),
        DatabaseModule,
        RateLimitModule,
        AuthModule.register({
          imports: [ApiTokensModule],
          authenticators: [ApiTokenAuthenticatorService],
        }),
        ApiTokensModule,
        ArtifactsModule,
        SharingModule,
        CommentsModule,
        UploadSessionsModule,
        McpModule,
        ClientConfigModule,
        HealthModule,
        WebModule.register(env.WEB_DIST_DIR),
      ],
      providers: [{ provide: APP_FILTER, useClass: AllExceptionsFilter }],
    };
  }
}
import type { NestExpressApplication } from '@nestjs/platform-express';
import cookieParser from 'cookie-parser';
import { json, type NextFunction, type Request, type Response } from 'express';
import { Logger } from 'nestjs-pino';
import { ENV } from './config/config.module.js';
import type { Env } from './config/config.types.js';

/** HTTP-level setup shared by `main.ts` and the e2e tests, so tests exercise the real app. */
export function configureApp(app: NestExpressApplication): void {
  const env = app.get<Env>(ENV);
  app.useLogger(app.get(Logger));
  // Behind a reverse proxy, take the client IP from X-Forwarded-For (rate limits, sessions).
  app.set('trust proxy', env.TRUST_PROXY_HOPS > 0 ? env.TRUST_PROXY_HOPS : false);
  app.use(cookieParser());
  // MCP clients send text artifacts inline as JSON strings, which escaping can make up to about
  // twice as long. Everything else keeps Nest's default 100 kB parser, added at init, which
  // skips bodies already parsed here. The upload pipeline still enforces MAX_ARTIFACT_BYTES.
  // Wrapped in a named function: Nest leaves out its own parser if a layer is named `jsonParser`.
  const mcpJson = json({ limit: env.MAX_ARTIFACT_BYTES * 2 + 64 * 1024 });
  app.use('/mcp', function mcpJsonParser(req: Request, res: Response, next: NextFunction) {
    mcpJson(req, res, next);
  });
  app.setGlobalPrefix('api', { exclude: ['mcp'] });
  app.enableShutdownHooks();
}

