import { createHash } from 'node:crypto';
import { PassThrough, type TransformCallback } from 'node:stream';

/** Passes bytes through unchanged, hashing them on the way; `digest()` once it has ended. */
export class Sha256PassThrough extends PassThrough {
  private readonly hash = createHash('sha256');
  private hex: string | null = null;

  override _transform(chunk: Buffer, encoding: BufferEncoding, callback: TransformCallback): void {
    this.hash.update(chunk);
    callback(null, chunk);
  }

  override _flush(callback: TransformCallback): void {
    this.hex = this.hash.digest('hex');
    callback();
  }

  /** SHA-256 (hex) of everything that passed through. Throws if the stream hasn't ended. */
  digest(): string {
    if (this.hex === null) throw new Error('The stream has not ended yet');
    return this.hex;
  }
}
