cat > sha256-pass-through.spec.ts <<'EOF'
import { createHash } from 'node:crypto';
import { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { Sha256PassThrough } from './sha256-pass-through.js';

const sha256 = (data: Buffer) => createHash('sha256').update(data).digest('hex');

describe('Sha256PassThrough', () => {
  it('passes the bytes through unchanged and hashes them', async () => {
    const chunks = [Buffer.from('hello '), Buffer.from('world')];
    const tap = new Sha256PassThrough();
    const received: Buffer[] = [];
    await pipeline(Readable.from(chunks), tap, async (source: AsyncIterable<Buffer>) => {
      for await (const chunk of source) received.push(chunk);
    });
    expect(Buffer.concat(received).toString()).toBe('hello world');
    expect(tap.digest()).toBe(sha256(Buffer.from('hello world')));
  });

  it('hashes an empty stream', async () => {
    const tap = new Sha256PassThrough();
    Readable.from([]).pipe(tap).resume();
    await new Promise((resolve) => tap.on('end', resolve));
    expect(tap.digest()).toBe(sha256(Buffer.alloc(0)));
  });

  it('has no digest before the stream has ended', () => {
    const tap = new Sha256PassThrough();
    tap.write(Buffer.from('partial'));
    expect(() => tap.digest()).toThrow('has not ended');
  });
});
EOF

