cd /home/work/projects/artifact_hub/apps/web/src && cat > lib/api/submission-key.ts <<'EOF'
/** One key per variables object; weak, so finished mutations take theirs with them. */
const keys = new WeakMap<object, string>();

/**
 * The `Idempotency-Key` of one submission: TanStack Query retries a mutation with the same
 * variables object, so every retry sends the same key, and the server does the work once.
 * The next submission (new variables) gets a new key.
 */
export function submissionKey(variables: object): string {
  let key = keys.get(variables);
  if (key === undefined) {
    key = crypto.randomUUID();
    keys.set(variables, key);
  }
  return key;
}
EOF
cat > lib/api/submission-key.spec.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { submissionKey } from './submission-key.ts';

describe('submissionKey', () => {
  it('is a UUID, the same for the same variables', () => {
    const variables = { body: 'Hi' };
    const key = submissionKey(variables);
    expect(key).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
    expect(submissionKey(variables)).toBe(key);
  });

  it('is new for other variables, even if equal', () => {
    expect(submissionKey({ body: 'Hi' })).not.toBe(submissionKey({ body: 'Hi' }));
  });
});
EOF
