/** A request made safe to repeat with an `Idempotency-Key` (`IdempotencyService.run`). */
export interface IdempotentOperation<T> {
  /** Does the work, and says which resource the answer is about. */
  execute(): Promise<IdempotentResult<T>>;
  /** The answer for a repeat: the resource as it is now. */
  replay(resourceId: string): Promise<T>;
  /**
   * What was sent, as a hash (`requestFingerprint`). A repeat must send the same. Taken after
   * `execute`, or after `skip` on a repeat, so it can cover a file that is still streaming.
   */
  fingerprint(): string;
  /** On a repeat, before its fingerprint is taken: e.g. reads the file of an upload. */
  skip?(): Promise<void>;
}

export interface IdempotentResult<T> {
  result: T;
  resourceId: string;
}
