      const report = await sweep();
      expect(report.expiredIdempotencyKeys).toBeGreaterThanOrEqual(1);
      const left = await db.query('SELECT key FROM idempotency_keys WHERE user_id = $1', [ada.id]);
      expect(left).toEqual([{ key: recent }]);
